    run(process.execPath,['--test','--test-concurrency=1',...unitNames],stage,'Geometry / door / vehicle / asset regression tests');
    run(process.execPath,['--test','--test-concurrency=1',at(stage,'tests/integration-030.test.mjs')],stage,'Actual Rapier + Arena integration gate');
    const vite=path.join(root,'node_modules','vite','bin','vite.js');
    if(!fs.existsSync(vite))throw Error('Vite is missing: npm ci must run before this update installer. No source files committed.');
    run(process.execPath,[vite,'build','--outDir','.bundle-check','--emptyOutDir'],stage,'Full Vite module/link check');
