    const report=await installAssets(stage,{offline:offlineAssets||process.env.PRIDA_OFFLINE_ASSETS==='1'});
    const reportName='public/prida030-assets.json';changes.set(reportName,fs.readFileSync(at(stage,reportName)));
    for(const [kind,entry] of Object.entries(report.models))if(entry.status==='downloaded'){
      const name=`public/models/prida030/${kind}.glb`;changes.set(name,fs.readFileSync(at(stage,name)));
    }
    const manifest=commitAt(root,changes);
    console.log('[PRIDA 0.30] INSTALLED: '+manifest.files.length+' files, doors + vehicles + Fort North + two villas.');
    console.log('[PRIDA 0.30] External model status: '+Object.entries(report.models).map(([k,v])=>k+'='+v.status).join(', '));
    return {status:'installed',files:manifest.files.length,assets:report.models};
