if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)) {
  try{await installAt(path.dirname(fileURLToPath(import.meta.url)),{checkOnly:process.argv.includes('--check'),rollback:process.argv.includes('--rollback'),offlineAssets:process.argv.includes('--offline-assets')});}
  catch(error){console.error('[PRIDA 0.30] '+(error?.stack||error));process.exitCode=1;}
}
